create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists user_info_set_updated_at on public.user_info;
create trigger user_info_set_updated_at
before update on public.user_info
for each row execute function public.set_updated_at();

drop trigger if exists train_record_set_updated_at on public.train_record;
create trigger train_record_set_updated_at
before update on public.train_record
for each row execute function public.set_updated_at();

drop trigger if exists kb_knowledge_set_updated_at on public.kb_knowledge;
create trigger kb_knowledge_set_updated_at
before update on public.kb_knowledge
for each row execute function public.set_updated_at();

drop trigger if exists kb_files_set_updated_at on public.kb_files;
create trigger kb_files_set_updated_at
before update on public.kb_files
for each row execute function public.set_updated_at();

drop trigger if exists user_kb_files_set_updated_at on public.user_kb_files;
create trigger user_kb_files_set_updated_at
before update on public.user_kb_files
for each row execute function public.set_updated_at();



-- 后端使用 service_role / secret key 访问；默认不对 anon 暴露业务数据
alter table public.user_info enable row level security;
alter table public.train_record enable row level security;
alter table public.chat_message enable row level security;
alter table public.kb_knowledge enable row level security;
alter table public.kb_files enable row level security;
alter table public.user_kb_files enable row level security;

grant usage on schema public to service_role;
grant all privileges on public.user_info, public.train_record, public.chat_message, public.kb_knowledge,
  public.kb_files, public.user_kb_files, public.health_check to service_role;
grant all privileges on all sequences in schema public to service_role;

